"use client";

import { useControllable } from "../hooks/use-controllable";
import { startTransition, useCallback, useId, useLayoutEffect, useMemo, useRef, useState } from "react";

import {
  AnalyticsGrid,
  AnalyticsShell,
  AnalyticsState,
  Cascade,
  exportCsv,
  mergeLabels,
  useDashboardData,
  useLiveTicker,
} from "./analytics-kit";

import {
  type AssetClass,
  type FinanceQuery,
  CLASS_ORDER,
  type FinanceLabels,
  defaultFinanceLabels,
  type FinanceDashboardProps,
  NO_CLASSES,
  NO_CANDLES,
} from "./analytics-finance/model";
import { useSteadyAssets, useMoney } from "./analytics-finance/hooks";
import { BalanceCard } from "./analytics-finance/balance-card";
import { CandleCard, AllocationCard, WatchlistCard, CoinsIcon, TransactionsCard } from "./analytics-finance/cards";

export {
  type AssetClass,
  type FinanceAsset,
  type FinanceTransaction,
  type FinanceData,
  type FinanceQuery,
  type AssetSpec,
  CLASS_ORDER,
  type FinanceLabels,
  defaultFinanceLabels,
  type FinanceDashboardProps,
} from "./analytics-finance/model";

/**
 * A finance / crypto dashboard: portfolio balance with a scrub-and-measure area chart, candles
 * with volume for the selected asset, allocation (donut or treemap), a live watchlist and the
 * transactions of the range.
 *
 * - Hover (or drag on touch) the balance chart: the big number rolls to that moment. Drag across
 *   it (touch: hold, then drag; keyboard: Shift + arrows) to measure the move between two points.
 * - Live: two prices tick every ~1.6 s with rolling digits and a brief up / down flash; the balance,
 *   sparklines and last candle follow. Pauses off-screen and in background tabs.
 * - The time range re-loads every card under a veil; charts tween to the new data.
 *
 * Props (see `FinanceDashboardProps`): `load` (required), `liveStep`, `liveInterval`
 * (`1600` ms), `range` / `defaultRange` (`"30d"`) / `onRangeChange`, `classes` / `defaultClasses` /
 * `onClassesChange`, `asset` / `defaultAsset` (`"BTC"`) / `onAssetChange`, `live` / `defaultLive` /
 * `onLiveChange`, `compare` / `defaultCompare` / `onCompareChange`, `onExport`, `currency` (`"USD"`),
 * `now`, `locale`, `headingLevel` (`"h2"`), `glass` (`"auto"`), `labels`
 * (`Partial<FinanceLabels>`), `className`.
 * Keyboard: Tab walks the header controls (the range control moves with the arrow keys, filter chips
 * toggle with Space or Enter, then Live, Compare and Export), the KPI tabs (arrow keys, Home and End)
 * and each chart, which is one tab stop whose arrow keys read its points. Panels with a table have a
 * Chart / Table switch.
 * Accessibility: a labelled region named by the title; panels are sections with headings one level
 * below `headingLevel`; loading is announced once ("Loading new data…", "Dashboard updated"), never on
 * every live tick; the Live toggle pauses updates (WCAG 2.2.2); the main charts have a table view; state
 * is never colour alone.
 * Glass and motion: a glass header and glass panels under an adaptive glass budget (frosted solid on
 * weak devices or when frames drop); charts mount near the viewport and draw in once; live ticks pause
 * off-screen and in hidden tabs; reduced motion removes draw-in and rolling digits and reduced
 * transparency makes the glass solid.
 * The balance chart adds Shift + arrow keys to measure the move between two points; the watchlist
 * rows are buttons that pick the asset shown in the candlestick card.
 *
 * @example
 * ```tsx
 * import { FinanceDashboard } from "@sheenui/theme";
 * import { financeDemoLoader } from "@sheenui/theme/demo-data";
 *
 * export function Example() {
 *   return (
 *     <FinanceDashboard load={financeDemoLoader} currency="EUR" locale="de-DE" defaultRange="12m" defaultAsset="NWT" defaultLive={false} />
 *   );
 * }
 * ```
 *
 * @see /dashboards/crypto-dashboard
 */
export function FinanceDashboard({
  load,
  status: statusProp = "auto",
  liveStep = null,
  liveInterval = 1600,
  range: rangeProp,
  defaultRange = "30d",
  onRangeChange,
  classes: classesProp,
  defaultClasses = NO_CLASSES,
  onClassesChange,
  asset: assetProp,
  defaultAsset = "BTC",
  onAssetChange,
  live: liveProp,
  defaultLive = true,
  onLiveChange,
  compare: compareProp,
  defaultCompare = false,
  onCompareChange,
  onExport,
  currency = "USD",
  now: nowProp,
  locale,
  headingLevel = 2,
  glass = "auto",
  labels: labelOverrides,
  className,
}: FinanceDashboardProps) {
  const L = useMemo<FinanceLabels>(
    () => ({
      ...mergeLabels(defaultFinanceLabels, labelOverrides),
      classes: { ...defaultFinanceLabels.classes, ...labelOverrides?.classes },
      pastRange: { ...defaultFinanceLabels.pastRange, ...labelOverrides?.pastRange },
      headers: { ...defaultFinanceLabels.headers, ...labelOverrides?.headers },
      types: { ...defaultFinanceLabels.types, ...labelOverrides?.types },
      statuses: { ...defaultFinanceLabels.statuses, ...labelOverrides?.statuses },
    }),
    [labelOverrides],
  );
  const titleId = useId();
  const rootRef = useRef<HTMLElement>(null);
  const [range, setRange] = useControllable(rangeProp, defaultRange, onRangeChange);
  const [classes, setClasses] = useControllable(classesProp, defaultClasses, onClassesChange);
  const [asset, setAsset] = useControllable(assetProp, defaultAsset, onAssetChange);
  const [live, setLive] = useControllable(liveProp, defaultLive, onLiveChange);
  const [compare, setCompare] = useControllable(compareProp, defaultCompare, onCompareChange);

  const [mountNow] = useState(() => new Date());
  const now = nowProp ?? mountNow;
  // Keyed by value, not identity: `classes` is a fresh array and `now` a fresh Date on every parent render.
  const classesKey = classes.join(",");
  const nowMs = now.getTime();
  const query = useMemo<FinanceQuery>(
    () => ({ range, classes: classesKey ? (classesKey.split(",") as AssetClass[]) : [], now: new Date(nowMs) }),
    [range, classesKey, nowMs],
  );
  const {
    data,
    status: dataStatus,
    retry,
    update,
    query: dataQuery,
  } = useDashboardData(load, query, `${range}|${classesKey}|${nowMs}`);
  const status = statusProp === "error" ? "error" : dataStatus;

  const liveRunning = useLiveTicker(
    live && status === "ready" && liveStep !== null,
    (tick) => {
      if (liveStep) update((d) => liveStep(d, tick));
    },
    { ref: rootRef, interval: liveInterval },
  );

  const loading = data === null || statusProp === "loading";
  const busy = status === "loading" && !loading;
  const money = useMoney(locale, currency);
  // Cards label their data with the range it was loaded for (the control may already show the next one).
  const shownRange = dataQuery?.range ?? range;

  // The candlestick follows the selected asset; if a filter hides it, the first visible one.
  const selected = data?.assets.find((a) => a.symbol === asset) ?? data?.assets[0] ?? null;

  // Tuples memoised by their parts, so an unchanged card keeps its props across live ticks.
  const selectedCandles = selected ? data?.candles[selected.symbol] : undefined;
  const hasData = data !== null;
  const series = data?.series;
  const previousSeries = data?.previous;
  const transactionRows = data?.transactions;
  const heroNow = useMemo(
    () => (series && previousSeries ? ([series, previousSeries, shownRange] as const) : null),
    [series, previousSeries, shownRange],
  );
  const candleNow = useMemo(
    () => (hasData ? ([selected, selectedCandles ?? NO_CANDLES, shownRange] as const) : null),
    [hasData, selected, selectedCandles, shownRange],
  );
  const txNow = useMemo(
    () => (transactionRows ? ([transactionRows, shownRange] as const) : null),
    [transactionRows, shownRange],
  );
  const allocation = useSteadyAssets(data?.assets ?? null);

  // Stable handlers and props for the memoised header controls and panels.
  const filters = useMemo(() => CLASS_ORDER.map((c) => ({ value: c, label: L.classes[c] })), [L]);
  const onFilters = useCallback((next: string[]) => setClasses(next as AssetClass[]), [setClasses]);
  // Picking an asset re-renders rows and remounts the candles: a transition keeps the click responsive.
  const onSelect = useCallback((symbol: string) => startTransition(() => setAsset(symbol)), [setAsset]);
  const latest = useRef({ data, query, onExport, range });
  useLayoutEffect(() => {
    latest.current = { data, query, onExport, range };
  });
  const exportData = useCallback(() => {
    const { data: d, query: q, onExport: custom, range: r } = latest.current;
    if (!d) return;
    if (custom) {
      custom(d, q);
      return;
    }
    const rows: (string | number)[][] = [];
    for (const a of d.assets)
      rows.push([
        a.name,
        a.symbol,
        L.classes[a.class],
        a.quantity,
        a.price,
        Math.round(a.quantity * a.price * 100) / 100,
      ]);
    rows.push([]);
    rows.push([L.headers.date, L.headers.type, L.headers.asset, L.headers.amount, L.headers.value, L.headers.status]);
    for (const t of d.transactions)
      rows.push([t.date, L.types[t.type], t.symbol, t.quantity, t.value, L.statuses[t.status]]);
    exportCsv(`${L.exportFile}-${r}.csv`, ["Holding", "Symbol", "Class", "Quantity", "Price", "Value"], rows);
  }, [L]);

  // Panels' empty states: "no match" while filtering, "no holdings yet" for an empty account.
  const filtered = classes.length > 0;
  const C = useMemo<FinanceLabels>(() => (filtered ? L : { ...L, noAssets: L.noHoldings }), [L, filtered]);

  return (
    <AnalyticsShell
      ref={rootRef}
      headingId={titleId}
      headingLevel={headingLevel}
      title={L.title}
      subtitle={L.description}
      icon={<CoinsIcon />}
      range={range}
      onRangeChange={setRange}
      filters={filters}
      activeFilters={classes}
      onFiltersChange={onFilters}
      live={live}
      onLiveChange={setLive}
      compare={compare}
      onCompareChange={setCompare}
      onExport={exportData}
      exportDisabled={!data}
      loading={busy}
      glass={glass}
      labels={L}
      className={className}
    >
      {status === "error" && !busy ? (
        <AnalyticsState kind="error" labels={L} onRetry={retry} />
      ) : statusProp === "empty" ||
        (data && !busy && !filtered && data.assets.length === 0 && data.transactions.length === 0) ? (
        // An account with nothing in it: one message, not five empty panels. (Filters that hide everything keep the panels: "no match".)
        <AnalyticsState kind="empty" labels={L} />
      ) : (
        <AnalyticsGrid>
          {/* Each panel takes new data a beat after the one before (only its own wrapper re-renders). */}
          <Cascade value={heroNow} index={0}>
            {(set) => (
              <BalanceCard
                set={set}
                compare={compare}
                live={liveRunning}
                money={money}
                locale={locale}
                currency={currency}
                labels={C}
              />
            )}
          </Cascade>
          <Cascade value={candleNow} index={1}>
            {(set) => <CandleCard set={set} money={money} locale={locale} currency={currency} labels={C} />}
          </Cascade>
          <Cascade value={allocation} index={2}>
            {(assets) => <AllocationCard assets={assets} money={money} locale={locale} labels={C} />}
          </Cascade>
          <WatchlistCard
            assets={data?.assets ?? null}
            selected={selected?.symbol ?? null}
            onSelect={onSelect}
            locale={locale}
            currency={currency}
            labels={C}
          />
          <Cascade value={txNow} index={3}>
            {(set) => <TransactionsCard set={set} money={money} locale={locale} labels={C} />}
          </Cascade>
        </AnalyticsGrid>
      )}
    </AnalyticsShell>
  );
}

"use client";

import { memo, useMemo, useState } from "react";

import { cn } from "../../lib/cn";
import { ChartTable } from "../../charts/chart-parts";
import { clamp } from "../../charts/chart-utils";
import { AnalyticsPanel, DeltaBadge, RollingNumber, changeRatio, type AnalyticsRange } from "../analytics-kit";
import { type FinanceData, type FinanceLabels, NO_SERIES, NO_NUMBERS } from "./model";
import { type Money, timeFormats } from "./hooks";
import { PortfolioChart } from "./portfolio-chart";

/* ---------- Balance (hero) ---------- */

/** The locale and label props every finance card shares. @internal */
export type CardBase = { locale?: string; labels: FinanceLabels };

/** The balance card: the total balance, its change and the portfolio chart. @internal */
export const BalanceCard = memo(function BalanceCard({
  set,
  compare,
  live,
  money,
  locale,
  currency,
  labels: L,
}: CardBase & {
  set: readonly [FinanceData["series"], number[], AnalyticsRange] | null;
  compare: boolean;
  live: boolean;
  money: Money;
  currency: string;
}) {
  const [series, previous, range] = set ?? [NO_SERIES, NO_NUMBERS, "30d" as const];
  const [active, setActive] = useState<number | null>(null);
  const [anchor, setAnchor] = useState<number | null>(null);
  const fmt = useMemo(() => timeFormats(range, locale), [range, locale]);
  const n = series.length;
  const at = (i: number | null) => (i === null ? undefined : series[clamp(i, 0, n - 1)]);
  const last = series[n - 1];
  const first = series[0];
  const shown = at(active) ?? last;
  const base = anchor !== null ? at(anchor) : first;
  const delta = shown && base ? shown.value - base.value : 0;
  const change = shown && base ? changeRatio(shown.value, base.value) : null;
  // Built once: this card re-renders on every scrub move, and an Intl.NumberFormat costs ~0.5 ms to construct.
  const signed = useMemo(
    () => new Intl.NumberFormat(locale, { style: "currency", currency, signDisplay: "exceptZero" }),
    [locale, currency],
  );
  const caption =
    anchor !== null && active !== null && base && shown
      ? L.between(fmt.point.format(Math.min(base.time, shown.time)), fmt.point.format(Math.max(base.time, shown.time)))
      : active !== null && shown
        ? fmt.point.format(shown.time)
        : L.pastRange[range];
  const prevLast = previous[previous.length - 1];
  const heroValue = shown?.value ?? 0;
  const scrubbing = active !== null;
  // Before the data arrives the (invisible) row shows wide stand-in figures, so it wraps on a phone as the real one will.
  const shownDelta = n === 0 ? 88_888.88 : delta;
  const shownChange = n === 0 ? 0.1234 : change;
  // A rolling number is many small motion elements: re-render it only when its value changes.
  const heroTicker = useMemo(
    () => (
      <RollingNumber
        value={heroValue}
        locale={locale}
        format={{ style: "currency", currency }}
        duration={scrubbing ? 0.3 : 0.8}
      />
    ),
    [heroValue, locale, currency, scrubbing],
  );

  const table = useMemo(() => {
    if (!set) return null;
    const rows = series.map((p, i) => ({
      time: fmt.point.format(p.time),
      value: Math.round(p.value * 100) / 100,
      previous: Math.round((previous[i] ?? 0) * 100) / 100,
    }));
    return (
      <ChartTable
        data={rows}
        index="time"
        indexLabel={L.headers.date}
        series={
          compare
            ? [
                { key: "value", label: L.portfolio },
                { key: "previous", label: L.previousPeriod },
              ]
            : [{ key: "value", label: L.portfolio }]
        }
        format={(v) => money.full.format(v)}
        caption={L.balance}
      />
    );
  }, [set, series, previous, compare, fmt, money, L]);

  return (
    <AnalyticsPanel
      index={0}
      title={L.balance}
      table={table}
      minHeight={349} // hero number + delta row + 236 px chart: the final height, reserved before the chart mounts
      ready={set !== null}
      labels={L}
      span={{ md: 2, lg: 3 }}
    >
      <div className="flex min-w-0 flex-col gap-1">
        <p className="text-4xl leading-tight font-semibold tracking-tight text-sheen-fg tabular-nums sm:text-5xl">
          {heroTicker}
        </p>
        <div className={cn("flex min-h-6 flex-wrap items-center gap-x-2 gap-y-1 text-sm", n === 0 && "invisible")}>
          <DeltaBadge change={shownChange} locale={locale} srLabel={L.change}>
            {signed.format(shownDelta).replace("-", "\u2212")} (
            {shownChange === null
              ? "–"
              : new Intl.NumberFormat(locale, {
                  style: "percent",
                  maximumFractionDigits: 2,
                  signDisplay: "never",
                }).format(Math.abs(shownChange))}
            )
          </DeltaBadge>
          <span className="text-sheen-fg-muted">{caption}</span>
          {/* Before the data arrives the row is invisible but laid out with a stand-in, so it wraps the same way. */}
          {compare && anchor === null && active === null && (
            <span className="flex items-center gap-1.5 text-sheen-fg-muted">
              · {L.vsPrevious(money.full.format(prevLast ?? 888_888.88))}
              <DeltaBadge
                change={last && prevLast !== undefined ? changeRatio(last.value, prevLast) : 0.1234}
                locale={locale}
                srLabel={L.change}
              />
            </span>
          )}
        </div>
      </div>
      <PortfolioChart
        series={series}
        previous={compare ? previous : null}
        active={active}
        anchor={anchor}
        onActive={setActive}
        onAnchor={setAnchor}
        live={live}
        formatValue={(v) => money.full.format(v)}
        formatAxisValue={(v) => money.compact.format(v)}
        formatAxisTime={(t) => fmt.axis.format(t)}
        formatPointTime={(t) => fmt.point.format(t)}
        labels={L}
      />
    </AnalyticsPanel>
  );
});

"use client";

import { memo, useEffect, useId, useMemo, useRef, useState } from "react";
import { motion } from "motion/react";

import { cn } from "../../lib/cn";
import { useSheenReducedMotion } from "../../hooks/use-preferences";
import { duration, ease } from "../../motion/tokens";
import { SegmentedControl } from "../../segmented/segmented";
import { Sparkline } from "../../charts/sparkline";
import { DonutChart } from "../../charts/donut-chart";
import { Treemap, TreemapTable, type TreemapNode } from "../../charts/treemap";
import { CandlestickChart, CandlestickTable, type Candle } from "../../charts/candlestick-chart";
import { chartFocusClass } from "../../charts/chart-utils";
import { AlertIcon, CheckIcon } from "../icons";
import { AnalyticsPanel, DeltaBadge, RollingNumber, changeRatio, type AnalyticsRange } from "../analytics-kit";
import {
  type FinanceAsset,
  type FinanceTransaction,
  CLASS_ORDER,
  type FinanceLabels,
  CLASS_SLOT,
  NO_CANDLES,
} from "./model";
import { type Money, timeFormats } from "./hooks";
import { type CardBase } from "./balance-card";

/* ---------- Candles ---------- */

/** The candlestick card of the finance dashboard, with its range controls. @internal */
export const CandleCard = memo(function CandleCard({
  set,
  money,
  locale,
  currency,
  labels: L,
}: CardBase & {
  set: readonly [FinanceAsset | null, Candle[], AnalyticsRange] | null;
  money: Money;
  currency: string;
}) {
  const [asset, candles, range] = set ?? [null, NO_CANDLES, "30d" as const];
  const first = candles[0];
  const change = asset && first ? changeRatio(asset.price, first.open) : null;
  const fmt = useMemo(() => timeFormats(range, locale), [range, locale]);
  const symbol = asset?.symbol;
  const name = asset?.name ?? "";
  const price = asset?.price ?? 0;
  // Keyed by symbol: another asset shows its own price at once (no roll from one asset's price to another's).
  const priceTicker = useMemo(
    () => (
      <RollingNumber
        key={symbol}
        value={price}
        locale={locale}
        format={money.options(price)}
        rollIn={false}
        duration={0.5}
      />
    ),
    [symbol, price, locale, money],
  );
  const chart = useMemo(
    () =>
      symbol ? (
        <CandlestickChart
          key={symbol}
          data={candles}
          average={7}
          height={280}
          volumeHeight={56}
          format={money.price}
          formatDate={(d) => fmt.point.format(d)}
          locale={locale}
          aria-label={`${L.candleTitle(symbol, name)} (${currency})`}
        />
      ) : null,
    [symbol, name, candles, money, fmt, locale, currency, L],
  );
  const table = useMemo(
    () =>
      symbol ? (
        <CandlestickTable
          data={candles}
          format={money.price}
          formatDate={(d) => fmt.point.format(d)}
          locale={locale}
          caption={L.candleTitle(symbol, name)}
        />
      ) : null,
    [symbol, name, candles, money, fmt, locale, L],
  );
  return (
    <AnalyticsPanel
      index={1}
      title={asset ? L.candleTitle(asset.symbol, asset.name) : L.priceHistory}
      description={L.candleDescription}
      aside={
        asset ? (
          <span className="flex items-center gap-2 text-sm font-semibold tabular-nums">
            {priceTicker}
            <DeltaBadge change={change} locale={locale} srLabel={L.change} />
          </span>
        ) : (
          // The price and change arrive with the data: keep their room so the header does not wrap later.
          <span aria-hidden className="invisible flex items-center gap-2 text-sm font-semibold tabular-nums">
            $00,000.00 <span>+0.00%</span>
          </span>
        )
      }
      table={table}
      // The chart's own height (candles + volume + its readout row), reserved before it mounts; the readout wraps
      // to more lines in a narrow dashboard, which the container-query class covers.
      minHeight={448}
      bodyClassName="min-h-[512px]! @md:min-h-[448px]!"
      ready={set !== null}
      labels={L}
      span={{ md: 2, lg: 3 }}
    >
      {set && !asset && (
        <p className="flex min-h-72 items-center justify-center text-sm text-sheen-fg-muted">{L.noAssets}</p>
      )}
      {chart}
    </AnalyticsPanel>
  );
});

/* ---------- Allocation ---------- */

/** The asset-allocation donut card, one slice per asset class. @internal */
export const AllocationCard = memo(function AllocationCard({
  assets,
  money,
  locale,
  labels: L,
}: CardBase & { assets: FinanceAsset[] | null; money: Money }) {
  const [view, setView] = useState<"donut" | "treemap">("donut");
  const byClass = useMemo(
    () =>
      CLASS_ORDER.map((c) => ({
        cls: c,
        holdings: (assets ?? [])
          .filter((a) => a.class === c && a.quantity > 0)
          .map((a) => ({ label: a.symbol, value: Math.round(a.quantity * a.price * 100) / 100 })),
      })).filter((g) => g.holdings.length > 0),
    [assets],
  );
  const tree = useMemo<TreemapNode[]>(
    () => byClass.map((g) => ({ label: L.classes[g.cls], color: CLASS_SLOT[g.cls], children: g.holdings })),
    [byClass, L],
  );
  const chart = useMemo(() => {
    if (!assets) return null;
    if (view === "treemap")
      return (
        <Treemap
          data={tree}
          height={300}
          format={(v) => money.compact.format(v)}
          locale={locale}
          emptyState={L.noAssets}
          aria-label={L.allocationTitle}
        />
      );
    const donut = byClass.map((g) => ({
      label: L.classes[g.cls],
      value: g.holdings.reduce((s, h) => s + h.value, 0),
      color: CLASS_SLOT[g.cls],
    }));
    return (
      <DonutChart
        data={donut}
        diameter={196}
        labels={{ center: L.total }}
        format={(v) => money.compact.format(v)}
        emptyState={L.noAssets}
        aria-label={L.allocationTitle}
        className="h-full content-center"
      />
    );
  }, [assets, view, tree, byClass, money, locale, L]);
  const table = useMemo(
    () =>
      assets && (
        <TreemapTable data={tree} format={(v) => money.full.format(v)} locale={locale} caption={L.allocationTitle} />
      ),
    [assets, tree, money, locale, L],
  );
  return (
    <AnalyticsPanel
      index={2}
      title={L.allocationTitle}
      aside={
        <SegmentedControl
          size="sm"
          aria-label={L.allocationView}
          items={[
            { value: "donut", label: L.donut },
            { value: "treemap", label: L.treemap },
          ]}
          value={view}
          onValueChange={(v) => setView(v as "donut" | "treemap")}
        />
      }
      table={table}
      // A legend of four classes wraps to a second line in the narrow column: always reserve it (the donut is centred),
      // so neither the data arriving nor a filter that hides a class moves the cards below.
      minHeight={view === "donut" ? 344 : 300}
      ready={assets !== null}
      labels={L}
      className="@5xl:col-start-4 @5xl:row-start-1"
    >
      {chart}
    </AnalyticsPanel>
  );
});

/* ---------- Watchlist ---------- */

/** The watchlist card: tracked symbols with price and change. @internal */
export const WatchlistCard = memo(function WatchlistCard({
  assets,
  selected,
  onSelect,
  locale,
  currency,
  labels: L,
}: CardBase & {
  assets: FinanceAsset[] | null;
  selected: string | null;
  onSelect: (symbol: string) => void;
  currency: string;
}) {
  // The rows reserved: the default eight until the first data is in, and still eight when that data is shorter (a
  // pre-set filter), so the cards below never move when it arrives. The list may shrink once the count changes later.
  const count = assets?.length ?? null;
  const [firstCount, setFirstCount] = useState<number | null>(null);
  if (count !== null && firstCount === null) setFirstCount(count);
  const rows = count === null || count === firstCount ? Math.max(8, count ?? 0) : count;
  return (
    <AnalyticsPanel
      index={3}
      title={L.watchlistTitle}
      description={L.watchlistDescription}
      // Eight 62 px rows is the list's final height (the default watchlist): reserve it while the symbols load too.
      minHeight={Math.max(360, rows * 62 + 2)}
      ready={assets !== null}
      labels={L}
      className="@5xl:col-start-4 @5xl:row-start-2"
    >
      {assets?.length === 0 ? (
        <p className="py-10 text-center text-sm text-sheen-fg-muted">{L.noAssets}</p>
      ) : (
        <ul className="@container -mx-2 flex flex-col">
          {(assets ?? []).map((a) => (
            <WatchRow
              key={a.symbol}
              asset={a}
              selected={a.symbol === selected}
              onSelect={onSelect}
              locale={locale}
              currency={currency}
              labels={L}
            />
          ))}
        </ul>
      )}
    </AnalyticsPanel>
  );
});

/** One watchlist row: symbol, price, change and a mini trend line. @internal */
export const WatchRow = memo(function WatchRow({
  asset,
  selected,
  onSelect,
  locale,
  currency,
  labels: L,
}: {
  asset: FinanceAsset;
  selected: boolean;
  onSelect: (symbol: string) => void;
  locale?: string;
  currency: string;
  labels: FinanceLabels;
}) {
  const reduced = useSheenReducedMotion();
  const change = changeRatio(asset.price, asset.open24h);
  const whole = Math.abs(asset.price) >= 1;
  const options = useMemo<Intl.NumberFormatOptions>(
    () => (whole ? { style: "currency", currency } : { style: "currency", currency, maximumFractionDigits: 4 }),
    [whole, currency],
  );
  // Selecting a row re-renders it: the rolling price only re-renders when the price changes.
  const ticker = useMemo(
    () => <RollingNumber value={asset.price} locale={locale} format={options} rollIn={false} duration={0.5} />,
    [asset.price, locale, options],
  );
  const priceText = new Intl.NumberFormat(locale, options).format(asset.price);
  const changeText =
    change === null
      ? ""
      : new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 2, signDisplay: "exceptZero" }).format(
          change,
        );
  // A brief tint behind the price when it ticks: up or down (the arrow badge says it in words).
  const prev = useRef(asset.price);
  const [flash, setFlash] = useState<{ dir: "up" | "down"; key: number } | null>(null);
  useEffect(() => {
    if (asset.price !== prev.current) {
      const dir = asset.price > prev.current ? "up" : "down";
      prev.current = asset.price;
      if (!reduced) setFlash((f) => ({ dir, key: (f?.key ?? 0) + 1 }));
    }
  }, [asset.price, reduced]);

  return (
    <li>
      <button
        type="button"
        aria-pressed={selected}
        onClick={() => onSelect(asset.symbol)}
        className={cn(
          "grid w-full grid-cols-[2rem_minmax(0,1fr)_auto] items-center gap-x-3 rounded-sheen-lg px-2 py-2 text-start @[17rem]:grid-cols-[2rem_minmax(0,1fr)_3.5rem_auto]",
          "min-h-12 touch-manipulation transition-colors duration-(--sheen-duration-fast) hover:bg-sheen-hover",
          "focus-visible:outline-solid focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sheen-focus",
          selected &&
            "bg-sheen-hover shadow-[inset_0_0_0_1px_var(--sheen-accent-border)] forced-colors:outline-2 forced-colors:outline-[Highlight] forced-colors:outline-solid",
        )}
      >
        <span
          aria-hidden
          className="flex size-8 items-center justify-center rounded-full text-2xs font-bold text-sheen-fg"
          style={{
            background: `color-mix(in oklab, var(--sheen-chart-${CLASS_SLOT[asset.class]}) 22%, var(--sheen-chart-surface))`,
          }}
        >
          {asset.symbol.slice(0, 3)}
        </span>
        {/* The name is made from the content (not an aria-label), so it always contains the visible text (WCAG 2.5.3). */}
        <span className="sr-only">{L.watchRow(asset.name, asset.symbol, priceText, changeText)}</span>
        <span aria-hidden className="flex min-w-0 flex-col">
          <span className="truncate text-sm font-semibold">{asset.symbol}</span>
          <span className="truncate text-xs text-sheen-fg-muted">{asset.name}</span>
        </span>
        <span aria-hidden className="hidden @[17rem]:block">
          <Sparkline values={asset.spark} height={28} area={false} variant="accent" />
        </span>
        <span aria-hidden className="relative flex flex-col items-end gap-0.5">
          {flash && (
            <motion.span
              key={flash.key}
              className={cn(
                "absolute -inset-x-1.5 -inset-y-0.5 rounded-sheen-sm",
                flash.dir === "up" ? "bg-sheen-success-soft" : "bg-sheen-danger-soft",
              )}
              initial={{ opacity: 1 }}
              animate={{ opacity: 0 }}
              transition={{ duration: duration.slower, ease: ease.out }}
            />
          )}
          <span className="relative text-sm font-semibold tabular-nums">{ticker}</span>
          <span className="relative">
            <DeltaBadge change={change} locale={locale} srLabel={L.change} />
          </span>
        </span>
      </button>
    </li>
  );
});

